void memory_test(void)
{
	int i;
	memory_test_buf_b = malloc(MEMORY_TEST_BYTES);
	if (memory_test_buf_b == 0) {
		printf("%s: malloc %s failed\n", __func__, MEMORY_TEST_BYTES);
		return;
	}
	printf("\n");
	printf("memory_test:buf_a=0x%x,buf_b=0x%x,test_bytes=0x%x\n", memory_test_buf_a, memory_test_buf_b, MEMORY_TEST_BYTES);
	for(i = 0; i < sizeof(tests)/sizeof(struct test); i++)
	{
		printf("test%d:%s\n", i, tests[i].name);
		tests[i].fp((ulv *)memory_test_buf_a, (ulv *)memory_test_buf_b, MEMORY_TEST_BYTES/sizeof(ulv));
	}
}

int private_ddr_test(void)
{
#define TEST_PRIVATE_VALUE0 0xffff0000
#define TEST_PRIVATE_VALUE1 0xffff0000
#define TEST_PRIVATE_INTERNAL 0x4000
	unsigned int *p_src;
	unsigned int tmp;
	printf("specific ddr test for hardware with oscilloscope.\n");
	printf("if use this case, you must set optimization level to -O0.\n");
	printf("%s start:\n", __func__);
	p_src = (unsigned int *)memory_test_buf_a;
	while (1) {
		tmp = *p_src;				//read new addr, in order to cause original cache data write to ddr & read new data to cache.
		*(p_src + 0) = TEST_PRIVATE_VALUE0;	//write specific data to cache
		*(p_src + 1) = TEST_PRIVATE_VALUE1;
		*(p_src + 2) = TEST_PRIVATE_VALUE0;
		*(p_src + 3) = TEST_PRIVATE_VALUE1;
		p_src += TEST_PRIVATE_INTERNAL / sizeof(unsigned int);
		if ((unsigned int)p_src >= ((unsigned int)memory_test_buf_a + MEMORY_TEST_BYTES))
			p_src = (unsigned int *)memory_test_buf_a;
	}
	return 0;
}
